# A tiny Bloom filter and a toy LSM memtable/SSTable to see the moving parts
import hashlib, bisect

class Bloom:
    def __init__(self, m=1024, k=3):
        self.m, self.k, self.bits = m, k, bytearray(m)
    def _hashes(self, item):
        for i in range(self.k):
            h = hashlib.sha256(f"{i}:{item}".encode()).digest()
            yield int.from_bytes(h[:8], "big") % self.m
    def add(self, item):
        for h in self._hashes(item): self.bits[h] = 1
    def might_contain(self, item):
        return all(self.bits[h] for h in self._hashes(item))    # False means definitely absent

class TinyLSM:
    def __init__(self, limit=4):
        self.mem, self.limit, self.sstables = {}, limit, []     # sstables: newest first
    def put(self, k, v):
        self.mem[k] = v
        if len(self.mem) >= self.limit: self._flush()
    def _flush(self):
        keys = sorted(self.mem)                                  # SSTable = sorted, immutable
        bloom = Bloom()
        for k in keys: bloom.add(k)
        self.sstables.insert(0, (keys, [self.mem[k] for k in keys], bloom))
        self.mem = {}
    def get(self, k):
        if k in self.mem: return self.mem[k]
        for keys, vals, bloom in self.sstables:                  # newest to oldest
            if not bloom.might_contain(k): continue              # skip the file cheaply
            i = bisect.bisect_left(keys, k)
            if i < len(keys) and keys[i] == k: return vals[i]
        return None

// B+ tree search sketch: descend internal nodes, binary-search inside each node
static final class Node {
    boolean leaf; int n; long[] keys = new long[ORDER - 1]; Node[] children = new Node[ORDER]; long[] values = new long[ORDER - 1];
}
Long search(Node node, long key) {
    while (!node.leaf) {
        int i = 0;
        while (i < node.n && key >= node.keys[i]) i++;   // pick the child whose range contains key
        node = node.children[i];                          // each hop = one page read in a real engine
    }
    int idx = Arrays.binarySearch(node.keys, 0, node.n, key);
    return idx >= 0 ? node.values[idx] : null;
}

-- Normalised schema with real constraints; the DB defends the model
CREATE TABLE customer (
  customer_id  BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name         TEXT NOT NULL,
  email        TEXT NOT NULL UNIQUE
);
CREATE TABLE product (
  product_id   BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name         TEXT NOT NULL,
  price_cents  INTEGER NOT NULL CHECK (price_cents >= 0)
);
CREATE TABLE orders (
  order_id     BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  customer_id  BIGINT NOT NULL REFERENCES customer ON DELETE RESTRICT,
  ordered_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE order_item (
  order_id     BIGINT NOT NULL REFERENCES orders ON DELETE CASCADE,
  product_id   BIGINT NOT NULL REFERENCES product,
  qty          INTEGER NOT NULL CHECK (qty > 0),
  unit_price_cents INTEGER NOT NULL,          -- price at purchase time (history, not redundancy)
  PRIMARY KEY (order_id, product_id)
);
CREATE INDEX order_item_product_idx ON order_item (product_id);   -- index the FK used in joins
CREATE INDEX orders_customer_idx ON orders (customer_id, ordered_at DESC);

-- Lost update prevented three ways (PostgreSQL)

-- 1) One atomic statement: the read and write can't interleave
UPDATE accounts SET balance = balance - 100 WHERE id = 1 AND balance >= 100;

-- 2) Pessimistic: lock the row first
BEGIN;
SELECT balance FROM accounts WHERE id = 1 FOR UPDATE;   -- others wait here
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
COMMIT;

-- 3) Optimistic: version check, retry if 0 rows were updated
UPDATE accounts SET balance = 900, version = version + 1 WHERE id = 1 AND version = 7;

-- Job queue with SKIP LOCKED: many workers, no double-processing
BEGIN;
SELECT id, payload FROM jobs WHERE status = 'pending' ORDER BY id LIMIT 1 FOR UPDATE SKIP LOCKED;
-- ... process, then ...
UPDATE jobs SET status = 'done' WHERE id = :id;
COMMIT;

# Retry loop for serialization failures and deadlocks (the application's part of the bargain)
import random, time
import psycopg
from psycopg import errors

def run_in_tx(conninfo, fn, retries=5):
    for attempt in range(retries):
        try:
            with psycopg.connect(conninfo) as conn:
                conn.isolation_level = psycopg.IsolationLevel.SERIALIZABLE
                with conn.transaction():
                    return fn(conn)
        except (errors.SerializationFailure, errors.DeadlockDetected):
            time.sleep(random.uniform(0, 0.05 * 2 ** attempt))      # backoff with jitter
    raise RuntimeError("transaction kept conflicting")
